mapper.select:
SELECT PC, NUM, MARKET, VARIABLE, VAL, VS, VS2, COMMENTS, ADD_DATE, DELETE_DATE, REGISTER_USER, REGISTER_DATETIME FROM HDOC_USER_DEFINED_RULES WHERE 1=1
AND PC = #{pc}
AND NUM = #{num}
AND MARKET = #{market}
AND VARIABLE LIKE CONCAT('%', #{variable}, '%')
AND VAL LIKE CONCAT('%', #{val}, '%')
AND VS LIKE CONCAT('%', #{vs}, '%')
AND VS2 LIKE CONCAT('%', #{vs2}, '%')
AND COMMENTS LIKE CONCAT('%', #{comments}, '%')
ORDER BY PC, NUM, MARKET
